  "privFooter": "Integritet och lagring",
  "privTitle": "Integritet och webbläsarlagring",
  "privClose": "Stäng integritetsmeddelande",
  "privWho": "Vem är ansvarig?",
  "privWhat": "Vad vi använder och varför",
  "privStorage": "Webbläsarlagring",
