  "privProviders": "Tjänsteleverantörer och internationella överföringar",
  "privRetention": "Lagringstid och radering",
  "privRights": "Dina rättigheter",
  "noticeReopen": "Lagringsmeddelande",
  "noticeLabel": "Meddelande om webbläsarlagring",
  "noticeText": "Cook använder webbläsarlagring för de matlagnings- och inloggningsfunktioner du använder. Ingen lagring för reklam eller analys läggs till.",
  "noticeClose": "Stäng lagringsmeddelande",
  "privDraftLabel": "Utkast – uppdaterat 28 oktober 2026.",
  "privDraft": "Kontofunktionerna testas just nu. Uppgifterna om operatören och tjänsterna nedan måste fyllas i före den offentliga lanseringen.",
  "privWho1": "Cook drivs av [operatörens juridiska namn och postadress]. Kontakta [e-postadress för integritetsfrågor] med frågor och begäranden om integritet. Uppgifterna måste fyllas i innan registreringen öppnar.",
  "privWhat1": "När du skapar ett konto använder vi din e-postadress, ett konto-id, uppgifter om lösenordsautentisering och verifieringsstatus för att tillhandahålla och skydda ditt konto. Lösenord hanteras av autentiseringsleverantören som säkra hashvärden; Cook lagrar inga läsbara lösenord. Vi sparar din köksplanering, valt språk, tema och måttenheter för att återställa dina inställningar på alla enheter. E-postadress och lösenord krävs för ett konto; du kan bläddra bland recept utan konto.",
  "privWhat2": "Behandlingen av konto och inställningar är nödvändig för att tillhandahålla den kontotjänst du begär (artikel 6.1 b i dataskyddsförordningen, GDPR). Begränsade uppgifter för säkerhet och förebyggande av missbruk kan behandlas med stöd av berättigat intresse (artikel 6.1 f), i den mån det är nödvändigt och efter en intresseavvägning. Mejl om verifiering och lösenordsåterställning är tjänstemeddelanden, inte marknadsföring. Kontofunktionen lägger inte till reklam eller analys.",
  "privStorage1": "Cook använder sessionStorage för att föra med ditt kök, dina framsteg i matlagningen och dina val mellan sidor i samma flik. När du är inloggad innehåller den även din inloggningssession. Webbläsaren rensar normalt detta när flikens session tar slut, men webbläsarens sessionsåterställning kan behålla det. När du loggar ut rensas Cooks flikdata. Att du stängt lagringsmeddelandet sparas bara i den fliken. Cooks egna skript sätter inga kakor. Dina webbhotell eller tjänsteleverantörer kan ha egen säkerhetsbehandling som måste dokumenteras före lanseringen.",
  "privStorage2": "OK och stängknappen på lagringsmeddelandet stänger bara meddelandet. De godkänner inte analys, reklam eller annan valfri spårning. All framtida icke-nödvändig lagring kräver ett separat val innan den börjar, med lika enkelt nej och återkallande.",
  "privOther1": "Den nuvarande röstfunktionen i receptlistan frågar country.is om ett ungefärligt land utifrån din IP-adress för att välja röstspråk. Om du använder mikrofonigenkänning kan din webbläsare skicka ljud till sin leverantör av taligenkänning. Du kan också skriva in ingredienserna. Dessa leverantörer, deras policyer och den rättsliga grunden för funktionerna måste granskas före den offentliga lanseringen.",
  "privProviders1": "Planerad kontoleverantör: Supabase (hanterad PostgreSQL och autentisering) med en vald databasregion inom EU. E-postleverantör: [leverantör]. Webbhotell: [leverantör]. Operatören måste bekräfta de faktiska leverantörerna, personuppgiftsbiträdesavtal, underbiträden, var loggar lagras och eventuella överföringar utanför EES. En databasregion inom EU utesluter inte i sig internationella överföringar. Ange vid behov tillämpligt beslut om adekvat skyddsnivå eller avtalsmässiga skyddsåtgärder och hur man får en kopia.",
  "privRetention1": "Kontoinställningar sparas så länge ditt konto är aktivt. Du kan begära radering via integritetskontakten ovan. Före lanseringen måste operatören ange hur raderingsbegäranden hanteras, när overifierade konton upphör och hur länge säkerhetsloggar och säkerhetskopior sparas. Raderade uppgifter kan finnas kvar i åtkomstbegränsade säkerhetskopior tills den dokumenterade lagringstiden löper ut.",
  "privRights1": "Beroende på tillämpliga villkor kan du begära tillgång, rättelse, radering, begränsning eller dataportabilitet, eller invända mot behandling som grundas på berättigat intresse. Kontakta operatören ovan; begäranden besvaras normalt inom en månad, och en eventuell laglig förlängning förklaras. Du kan klaga hos din tillsynsmyndighet, bland annat ungerska NAIH på naih.hu. Cook använder inte kontoinställningar för automatiserade beslut med rättsliga följder eller liknande betydande följder.",
