  "1 cm rings": "1 cm ringar",
  "Slice the onion": "Skiva löken",
  "Halve the onion and slice it thinly.": "Halvera löken och skiva den tunt.",
  "Cut the peppers": "Skär paprikorna",
  "Remove the stems and seeds and cut the peppers into 1 cm rings.": "Ta bort stjälk och kärnor och skär paprikorna i 1 cm ringar.",
  "Cut into rings": "I ringar",
  "Cut the tomatoes": "Skär tomaterna",
  "Cut the tomatoes into chunks.": "Skär tomaterna i bitar.",
  "Chunks": "I bitar",
  "Heat the oil in the large frying pan and cook the onion until soft and glassy.": "Värm oljan i den stora stekpannan och fräs löken mjuk och glansig.",
  "Soft, glassy": "Mjuk, glansig",
  "Peppers in": "Tillsätt paprikorna",
  "Take the pan off the heat for a moment, stir in the paprika, then add the peppers. Cook, stirring now and then, until they soften and lose their bright colour.": "Ta pannan från värmen en stund, rör ner paprikapulvret och tillsätt sedan paprikorna. Stek under omrörning då och då tills de mjuknar och tappar sin klara färg.",
  "Peppers soft": "Paprikorna mjuka",
  "Add the tomatoes, the salt and the sugar. Simmer uncovered until the tomatoes fall apart and most of the liquid is gone.": "Tillsätt tomaterna, saltet och sockret. Låt sjuda utan lock tills tomaterna faller sönder och det mesta av vätskan har kokat bort.",
  "Thick, saucy": "Tjock och krämig",
  "Serve hot with fresh bread (or rice).": "Servera varmt med färskt bröd (eller ris).",
  "Slice the onion … Cut the tomatoes": "Skiva löken … Skär tomaterna",
  "Soften the onion … Tomatoes in": "Mjuka löken … Tomaterna i",
  "Beat the eggs": "Vispa äggen",
  "Beat the eggs with a fork in a bowl.": "Vispa äggen med en gaffel i en skål.",
  "Beaten": "Vispade",
  "Pour the eggs over the lecsó and stir gently until they have just set.": "Häll äggen över lecsón och rör försiktigt tills de precis har stelnat.",
  "Eggs just set": "Äggen precis stelnade",
  "Soften the onion … Eggs in": "Mjuka löken … Äggen i",
  "Slice the sausage": "Skär korven",
