  "Sausage in": "Tillsätt korven",
  "Add the sausage and fry for 2 minutes so it releases its red fat.": "Tillsätt korven och stek 2 minuter så att den släpper sitt röda fett.",
  "Red fat in the pan": "Rött fett i pannan",
  "Slice the onion … Slice the sausage": "Skiva löken … Skär korven",
  "With rum": "Med rom",
