  "separated": "delade",
  "Turn the oven on to 180 °C conventional (160 °C fan). Line the baking tray with baking paper.": "Sätt ugnen på 180 °C över- och undervärme (160 °C varmluft). Klä plåten med bakplåtspapper.",
  "Oven on, tray lined": "Ugnen på, plåten klädd",
  "Soak the raisins": "Blötlägg russinen",
  "Put the raisins in a small bowl and pour half the rum over them (or a little warm water).": "Lägg russinen i en liten skål och häll över hälften av romen (eller lite ljummet vatten).",
  "Soaking": "Blötläggs",
  "Separate the eggs": "Dela äggen",
  "Separate the eggs for the sponge: whites into a clean bowl, yolks into another.": "Dela äggen till sockerkakan: vitorna i en ren skål, gulorna i en annan.",
  "Separated": "Delade",
  "Whisk the whites": "Vispa vitorna",
  "Whisk the whites to soft peaks, then add half the sugar a little at a time and whisk until stiff and glossy.": "Vispa vitorna till mjukt skum, tillsätt sedan hälften av sockret lite i taget och vispa till ett fast, glansigt skum.",
  "Stiff, glossy peaks": "Fast, glansigt skum",
  "Yolks in": "Tillsätt gulorna",
  "Beat the yolks with the rest of the sugar until pale, then fold them gently into the whites.": "Vispa gulorna med resten av sockret tills de är ljusa och vänd sedan försiktigt ner dem i vitorna.",
  "Light and airy": "Lätt och luftig",
  "Fold in the flour": "Vänd ner mjölet",
  "Mix the flour with the baking powder and fold it in gently in two goes.": "Blanda mjölet med bakpulvret och vänd ner det försiktigt i två omgångar.",
  "Walnut and cocoa": "Valnöt och kakao",
  "Divide the batter in two bowls. Fold the ground walnuts into one and the cocoa into the other.": "Dela smeten i två skålar. Vänd ner de malda valnötterna i den ena och kakaon i den andra.",
  "Two batters": "Två smeter",
  "Spread on the tray": "Bred ut på plåten",
  "Fold a ridge in the middle of the baking paper and spread the walnut batter on one half, the cocoa batter on the other, about 1 cm thick.": "Vik en kant mitt på bakplåtspappret och bred ut valnötssmeten på ena halvan och kakaosmeten på den andra, cirka 1 cm tjockt.",
  "Evenly spread": "Jämnt utbredd",
  "Bake the sponge": "Grädda sockerkakan",
  "Bake until springy and a toothpick comes out clean.": "Grädda tills kakan fjädrar tillbaka vid tryck och en provsticka kommer ut ren.",
  "Springy, toothpick clean": "Fjädrar, provsticka ren",
  "Cool the sponge": "Låt kakan svalna",
  "Let the sponge cool on the rack.": "Låt sockerkakan svalna på gallret.",
  "Custard base": "Krämbas",
  "Whisk the yolks, the sugar and the flour smooth with a few spoons of the milk. Heat the rest of the milk in the saucepan until it steams.": "Vispa gulor, socker och mjöl slätt med några skedar mjölk. Värm resten av mjölken i kastrullen tills den ångar.",
  "Smooth base, milk steaming": "Slät bas, ångande mjölk",
  "Cook the custard": "Koka krämen",
  "Pour the hot milk onto the yolks while whisking, pour it all back into the pan and cook on low, whisking all the time, until thick. Stir in the vanilla.": "Häll den varma mjölken över gulorna under vispning, häll tillbaka allt i kastrullen och koka på låg värme under ständig vispning tills det tjocknar. Rör ner vaniljen.",
  "Thick, coats the whisk": "Tjock, täcker vispen",
  "Cool the custard": "Låt krämen svalna",
  "Pour into a bowl, press cling film onto the surface and let it cool.": "Häll den i en skål, lägg plastfolie direkt mot ytan och låt svalna.",
  "Cool, no skin": "Kall, ingen hinna",
  "Make the syrup": "Gör sockerlagen",
  "Boil the water and the sugar with the lemon zest for 2 minutes. Take off the heat and add the rest of the rum.": "Koka vatten och socker med citronskal i 2 minuter. Ta från värmen och tillsätt resten av romen.",
  "Syrupy": "Sirapsaktig",
  "Chop the walnuts": "Hacka valnötterna",
  "Roughly chop the walnuts for the layers.": "Grovhacka valnötterna till lagren.",
  "Tear the sponges into rough pieces. In a deep dish, layer the walnut sponge, half the syrup, half the custard, half the raisins and walnuts; then the cocoa sponge, the rest of the syrup, raisins and walnuts, and finish with the custard.": "Riv sockerkakorna i grova bitar. Varva i en djup form valnötskaka, hälften av sockerlagen, hälften av krämen, hälften av russinen och valnötterna; sedan kakaokaka, resten av sockerlagen, russin och valnötter, och avsluta med krämen.",
  "Cover and chill for at least 4 hours; overnight is best.": "Täck och ställ kallt i minst 4 timmar; helst över natten.",
  "Set and cold": "Stelnad och kall",
